+  while fOutputCount > 0 do
+  begin
+    sent := mormot.net.sock.Send(fSocket.Socket,
+      @PByteArray(fOutput)[fOutputPos], fOutputCount, MSG_NOSIGNAL);
+    if sent > 0 then
+    begin
+      inc(fOutputPos, sent);
+      dec(fOutputCount, sent);
